public class Probe3 {
    public static void main(String[] a) {
        // DOM mutation reflected in output
        Document d = Jsoup.parse("<?xml version=\"1.0\"?><root><a>1</a><b>2</b></root>", "", Parser.xmlParser());
        d.selectFirst("a").text("one");
        d.selectFirst("b").remove();
        d.selectFirst("root").appendElement("c").text("3");
        Element moved = d.selectFirst("c");
        d.selectFirst("root").prependChild(moved);
        System.out.println("== mutated\n" + d.html());

        // repeated output stable
        String o1 = d.html(), o2 = d.html();
        System.out.println("== stable: " + o1.equals(o2));

