        Document d1 = Jsoup.parse("<root><x>1</x></root>", "", Parser.xmlParser());
        Document d2 = Jsoup.parse("<root><x>2</x></root>", "", Parser.xmlParser());
        d1.selectFirst("x").text("CHANGED");
        System.out.println("== d1: " + d1.html());
