import os
import pathlib
import shutil
import subprocess
import sys
import tempfile

# Coverage: public streaming contract -> Java cases core/io -> assertions in Harness.
# Core catches wrong ordering, deduplication, leading separators, empty/prefix handling,
# mixed node types, per-document settings, detached defaults, repeatability, mutation, and parity.
# IO catches wrapped causes, prefix preservation, separator short-circuit, and mid-node stop.
# Each assertion has a concrete counterexample: concatenating first/unique nodes, caching output,
# sharing settings, writing separators early, swallowing IOException, or continuing after failure.
root = pathlib.Path(__file__).resolve().parents[1]
sys.path.insert(0, str(root))

for tool in ("mvn", "javac", "java"):
    if shutil.which(tool) is None:
        print("ENVIRONMENT_FAILURE: missing " + tool, file=sys.stderr)
        raise SystemExit(2)

mode = "all"
if len(sys.argv) > 1:
    if len(sys.argv) != 3 or sys.argv[1] != "--demo" or sys.argv[2] not in ("core", "io", "all"):
        print("ADAPTER_FAILURE: expected optional --demo core|io|all", file=sys.stderr)
        raise SystemExit(2)
    mode = sys.argv[2]

build = subprocess.run(["mvn", "-q", "-DskipTests", "compile"], cwd=str(root), text=True)
if build.returncode != 0:
    print("PRODUCT_BUILD_FAILURE: Maven compile failed", file=sys.stderr)
    raise SystemExit(1)

