public class Harness {
  static void eq(Object a, Object b, String m) {
    if (a == null ? b != null : !a.equals(b)) throw new AssertionError(m + " expected=" + a + " actual=" + b);
  }
  static void ok(boolean v, String m) { if (!v) throw new AssertionError(m); }

  static final class Failing implements Appendable {
    final StringBuilder out = new StringBuilder();
    int remaining;
    final boolean failNewline;
    Failing(int n, boolean nl) { remaining = n; failNewline = nl; }
    public Appendable append(CharSequence s, int a, int b) throws IOException {
      for (int i = a; i < b; i++) append(s.charAt(i));
      return this;
    }
    public Appendable append(CharSequence s) throws IOException { return append(s, 0, s.length()); }
    public Appendable append(char c) throws IOException {
      if (failNewline && c == '\n') throw new IOException("separator failure");
      if (remaining-- <= 0) throw new IOException("append failure");
      out.append(c); return this;
    }
    public String toString() { return out.toString(); }
  }

  static void core() {
    Document d = Jsoup.parse("<p>One</p><p>Two</p>");
