    eq(expected, ns.outerHtml(new StringBuilder()).toString(), "builder parity");
    eq("PRE:" + expected, ns.outerHtml(sb).toString(), "existing prefix");
    eq(expected, ns.outerHtml(), "string parity");
    eq(expected, ns.toString(), "toString parity");
    Nodes<Node> empty = new Nodes<Node>();
    eq("keep", empty.outerHtml(new StringBuilder("keep")).toString(), "empty append");

    Element p = new Element("p").text("X");

